#!/usr/bin/env python3
"""Temporary real-browser multi-touch and offline sample renderer QA, not physical iOS."""
from pathlib import Path
import sys
p=Path(__file__).resolve().parents[1]/'dist/__music-review.html'
if '--clean' in sys.argv:p.unlink(missing_ok=True);raise SystemExit
p.write_text(r'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Ensaios da Casa da Música</title><style>body{font:16px system-ui;background:#f5f1e5;color:#304635;margin:16px}button{padding:14px;margin:5px}iframe{width:390px;height:820px;border:1px solid #ccd2be;border-radius:16px;float:right;margin:0 12px}pre{white-space:pre-wrap;max-width:760px}h1{font-size:24px}</style><h1>Som gravado e instrumentos dentro da cena</h1><p>Eventos de toque programáticos no navegador; não é um teste físico em iPhone.</p><button id="notes">Testar oito dedos no teclado</button><button id="drums">Testar dois tambores juntos</button><button id="offline">Renderizar mixagem real de 24 vozes</button><iframe id="game" src="index.html"></iframe><pre id="result">Preparando a prévia…</pre><script src="music-audio.js"></script><script>
const f=document.getElementById('game'),out=document.getElementById('result');const timer=setInterval(()=>{if(f.contentWindow.PippoActivities&&f.contentWindow.PippoCanon?.ready){clearInterval(timer);out.textContent='Prévia pronta. Escolha um ensaio.'}},100);
const delay=t=>new Promise(r=>setTimeout(r,t));
async function setup(kind){const w=f.contentWindow,d=w.document;d.querySelector('[data-place="yard"]').click();d.querySelector('[data-place="music"]').click();d.querySelector('button[data-instrument="'+kind+'"]').click();for(let i=0;i<100&&!w.PippoActivities.getMusicState().audio.ready;i++)await delay(50);if(!w.PippoActivities.getMusicState().audio.ready)throw Error('samples not ready');return w}
function touch(w,id,el){const b=el.getBoundingClientRect();return new w.Touch({identifier:id,target:el,clientX:b.x+b.width/2,clientY:b.y+b.height/2})}
function send(w,type,changed,touches){w.document.getElementById('musicPanel').dispatchEvent(new w.TouchEvent(type,{bubbles:true,cancelable:true,changedTouches:changed,touches,targetTouches:touches}))}
async function test(kind,count){try{const w=await setup(kind),d=w.document,els=[...d.querySelectorAll(kind==='keyboard'?'[data-note]':'[data-piece]')].slice(0,count),ts=els.map((el,i)=>touch(w,100+i,el));send(w,'touchstart',ts,ts);await delay(80);const start=w.PippoActivities.getMusicState();if(start.held!==count||start.audio.voices<count)throw Error('simultaneous touches lost: '+JSON.stringify(start));out.textContent=JSON.stringify({stage:'toques simultâneos',state:start,lit:els.filter(e=>e.classList.contains('playing')).length},null,2);await delay(450);send(w,'touchend',[ts[0]],ts.slice(1));await delay(30);const firstUp=w.PippoActivities.getMusicState();if(firstUp.held!==count-1)throw Error('one release removed other fingers');send(w,'touchcancel',ts.slice(1),[]);const cancelled=w.PippoActivities.getMusicState();if(cancelled.held!==0||kind==='keyboard'&&cancelled.audio.voices!==0)throw Error('cancel did not clean notes');for(const el of els)el.focus();if(d.getElementById('stage').scrollTop!==0)throw Error('instrument focus scrolled the scene');send(w,'touchstart',ts,ts);d.getElementById('pause').click();await delay(30);const paused=w.PippoActivities.getMusicState();d.getElementById('pause').click();await delay(40);const resumed=w.PippoActivities.getMusicState();if(paused.held||paused.audio.voices||resumed.audio.voices)throw Error('pause replay');out.textContent='PASS: '+kind+' — '+count+' toques simultâneos, liberação independente, cancelamento, pausa e retomada sem repetição.\n'+JSON.stringify({start,firstUp,cancelled,paused,resumed},null,2)}catch(e){out.textContent='FAIL: '+e.stack}}
document.getElementById('notes').onclick=()=>test('keyboard',8);document.getElementById('drums').onclick=()=>test('drum',2);
document.getElementById('offline').onclick=async()=>{try{out.textContent='Renderizando áudio local…';const offline=new OfflineAudioContext(1,44100*4,44100);class Adapter{constructor(){return new Proxy(offline,{get(o,k){if(k==='state')return 'running';if(k==='resume')return ()=>Promise.resolve();const v=o[k];return typeof v==='function'?v.bind(o):v}})}}const a=PippoAudio.create({AudioContext:Adapter});await a.load();a.setVolume(.8);for(let i=0;i<24;i++)a.play('stress'+i,'drum',0);const buffer=await offline.startRendering(),data=buffer.getChannelData(0);let peak=0,sum=0;for(const v of data){peak=Math.max(peak,Math.abs(v));sum+=v*v}if(peak>1||peak<.01)throw Error('invalid mixed output '+peak);out.textContent='PASS: mixagem real renderizada de 24 golpes simultâneos.\n'+JSON.stringify({peak,rms:Math.sqrt(sum/data.length),duration:buffer.duration,finite:data.every(Number.isFinite)},null,2)}catch(e){out.textContent='FAIL: '+e.stack}};
</script></html>''')
print('Open /__music-review.html; --clean before publishing.')
